package org.eclipse.rdf4j.query.explanation;

import org.eclipse.rdf4j.common.annotation.Experimental;

/**
 * A suppressed diagnostic attached to the original failed explanation exception. Keeping the original exception
 * preserves evaluation error semantics while making the partial execution profile available to callers.
 */
@Experimental
public final class ExplanationExecutionException extends RuntimeException {

	private static final long serialVersionUID = 1L;
	private final QueryExecutionProfile executionProfile;

	public ExplanationExecutionException(QueryExecutionProfile executionProfile) {
		super("Telemetry execution " + executionProfile.status() + ": " + executionProfile.detail(), null, false,
				false);
		this.executionProfile = executionProfile;
	}

	public QueryExecutionProfile getExecutionProfile() {
		return executionProfile;
	}
}
